UPDATE settings SET value = REPLACE(value, '1回の投稿でタイミングをいくつでも追加でき、', '1回の投稿でタイミングを20個まで追加でき、'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE key = 'about' AND instr(value, '1回の投稿でタイミングを20個まで追加でき、') = 0;
UPDATE settings SET value = REPLACE(value, '3. 申請後に出る受付番号で、審査状況を確認できます。審査はタイミングごとで、承認されたものから公開されます。', '3. 申請後に出る受付番号で、審査状況を確認できます（画面の下の「審査状況」から）。審査はタイミングごとで、承認されたものから公開されます。
4. 同じ「審査状況」の画面から、投稿の取り下げや、X の ID・応援コードの変更の申請もできます（このブラウザで投稿したものだけ）。'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE key = 'about' AND instr(value, '3. 申請後に出る受付番号で、審査状況を確認できます（画面の下の「審査状況」から）。審査はタイミングごとで、承認されたものから公開されます。
4. 同じ「審査状況」の画面から、投稿の取り下げや、X の ID・応援コードの変更の申請もできます（このブラウザで投稿したものだけ）。') = 0;
UPDATE settings SET value = REPLACE(value, '- 保存するのは、投稿の内容・X の ID・応援コード（入力した場合のみ）と、お問い合わせの内容だけです。', '- 保存するのは、投稿の内容・X の ID・応援コード（入力した場合のみ）と、お問い合わせの内容（返信先を入力した場合はそれも）だけです。'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE key = 'terms' AND instr(value, '- 保存するのは、投稿の内容・X の ID・応援コード（入力した場合のみ）と、お問い合わせの内容（返信先を入力した場合はそれも）だけです。') = 0;
UPDATE settings SET value = REPLACE(value, '- 本アプリは Cloudflare（配信・ロボット対策）などの外部サービスを利用しており、IP アドレスなどの接続情報が各サービスに送られることがあります。広告やアクセス解析のツールは使っていません。', '- 本アプリは Cloudflare（配信・ロボット対策）などの外部サービスを利用しており、IP アドレスなどの接続情報が各サービスに送られることがあります。広告やアクセス解析のツールは使っていません。
- 投稿の取り下げなどに使う受付番号・取り下げ用のキー、次の投稿で使う X の ID・応援コード、投稿途中の動画は、お使いのブラウザの中にだけ保存されます（サーバーには送りません）。
- 対応が済んだお問い合わせは、90日後に自動で削除します。'), updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE key = 'terms' AND instr(value, '- 本アプリは Cloudflare（配信・ロボット対策）などの外部サービスを利用しており、IP アドレスなどの接続情報が各サービスに送られることがあります。広告やアクセス解析のツールは使っていません。
- 投稿の取り下げなどに使う受付番号・取り下げ用のキー、次の投稿で使う X の ID・応援コード、投稿途中の動画は、お使いのブラウザの中にだけ保存されます（サーバーには送りません）。
- 対応が済んだお問い合わせは、90日後に自動で削除します。') = 0;
